'use strict';
(()=>{
 const $=id=>document.getElementById(id),dialog=$('buildDialog');let data,categories,worker,generation=0,loading=false;
 const manualGoals=new Map();
 const types={'great-sword':'대검','long-sword':'태도','sword-shield':'한손검','dual-blades':'쌍검',hammer:'해머','hunting-horn':'수렵피리',lance:'랜스',gunlance:'건랜스','switch-axe':'슬래시액스','charge-blade':'차지액스','insect-glaive':'조충곤','light-bowgun':'라이트보우건','heavy-bowgun':'헤비보우건',bow:'활'};
 // 거극 아티어: MHDB snapshot IDs for the fourteen weapon types.
 const gogArtianIds=WeaponBonuses.gogIds;
 const parts={weapon:'무기',head:'머리',chest:'상의',arms:'팔',waist:'허리',legs:'다리',talisman:'호석'};
 function option(select,value,label){const o=document.createElement('option');o.value=value;o.textContent=label;select.append(o);}
 function stop(message){generation++;worker?.terminate();worker=null;$('buildStart').disabled=!data;$('buildCancel').disabled=true;if(message)$('buildStatus').textContent=message;}
 function invalidate(){if(dialog.hidden)return;stop('조건이 변경되었습니다. 다시 검색하세요.');$('buildResults').replaceChildren();$('buildError').textContent='';}
 function weaponHint(){const w=data.weapons.find(w=>w.id===Number($('buildWeapon').value)),gog=gogArtianIds.has(w?.id);$('buildWeaponBonuses').hidden=false;$('buildWeaponBonusStatus').textContent=gog?'거극 부여 스킬: 실제 무기의 시리즈·그룹을 각각 지정하세요.':'거극 아티어 선택 시 부여 스킬을 지정할 수 있습니다.';for(const id of ['buildWeaponSeries','buildWeaponGroup']){if(!gog)$(id).value='0';$(id).disabled=!gog;}$('buildWeaponHint').textContent=gog?'거극 아티어의 시리즈·그룹 스킬을 고정 무기 옆에서 지정할 수 있습니다. 복원 보너스 수치는 반영하지 않습니다.':w?.category==='artian'?'아티어 기본 스킬·슬롯으로 계산합니다. 복원 보너스는 반영하지 않습니다.':'제작 무기의 강화 경로에서 마지막 단계만 표시합니다.';syncWeaponGoals();}
 function weapons(){const s=$('buildWeapon');s.replaceChildren();const choices=data.weapons.filter(w=>w.kind===$('buildType').value).sort((a,b)=>Number(gogArtianIds.has(b.id))-Number(gogArtianIds.has(a.id))||b.rarity-a.rarity||a.name.localeCompare(b.name,'ko'));for(const [category,label]of [['artian','아티어 · 기본 구성'],['crafted-final','제작 · 최종 강화']]){const group=document.createElement('optgroup');group.label=label;for(const w of choices.filter(w=>w.category===category))option(group,w.id,`${w.name} · R${w.rarity} · 슬롯 ${w.slots.join('/')||'없음'}`);if(group.children.length)s.append(group);}weaponHint();}
 function renderSkillMenu(){
  const menu=$('buildGoals');menu.replaceChildren();const nav=$('buildSkillCategories');nav.replaceChildren();
  function categoryButton(key,label){const button=document.createElement('button');button.type='button';button.textContent=label;button.dataset.skillCategory=key;button.setAttribute('aria-pressed',key===''?'true':'false');button.addEventListener('click',()=>{for(const b of nav.children)b.setAttribute('aria-pressed',String(b===button));filterSkills();});nav.append(button);}
  categoryButton('','전체');for(const group of categories.groups){categoryButton(group.key,group.label);const section=document.createElement('section');section.className='skill-menu-group';section.dataset.category=group.key;text(section,'h3',group.label);const grid=document.createElement('div');grid.className='skill-menu-grid';for(const skill of data.skills.filter(s=>group.ids.includes(s.id)&&!data.weaponOnlySkillIds.includes(s.id)).sort((a,b)=>group.displayOrder?group.ids.indexOf(a.id)-group.ids.indexOf(b.id):a.name.localeCompare(b.name,'ko'))){const label=document.createElement('label');label.className='skill-menu-item';label.classList.toggle('is-bonus',['set','group'].includes(skill.kind));label.dataset.search=normalizeSkill([skill.name,...skill.ranks.map(r=>r.name||'')].join(' '));text(label,'span',skill.name);const select=document.createElement('select');select.className='build-skill-level';select.dataset.skillId=skill.id;option(select,0,'—');for(const rank of skill.ranks)option(select,rank.level,rank.pieces?`${rank.name} · ${rank.pieces}부위`:`Lv.${rank.level}`);select.addEventListener('change',()=>{const level=Number(select.value);if(level)manualGoals.set(skill.id,level);else manualGoals.delete(skill.id);syncWeaponGoals();});label.append(select);const note=document.createElement('small');note.className='weapon-skill-note';note.hidden=true;label.append(note);grid.append(label);}section.append(grid);menu.append(section);}filterSkills();syncWeaponGoals();
 }
 const normalizeSkill=value=>value.toLocaleLowerCase('ko').replace(/\s/g,'');
 function selectedGoals(){const intrinsic=intrinsicGoals(),ids=new Set([...manualGoals.keys(),...Object.keys(intrinsic).map(Number)]);return [...ids].map(id=>({id,level:Math.max(intrinsic[id]||0,manualGoals.get(id)||0)})).filter(g=>g.level>0);}
 function intrinsicGoals(){const w=data?.weapons.find(w=>w.id===Number($('buildWeapon').value));return w?.category==='crafted-final'?w.skills:{};}
 function syncWeaponGoals(){const intrinsic=intrinsicGoals();for(const select of document.querySelectorAll('.build-skill-level')){const id=Number(select.dataset.skillId),base=intrinsic[id]||0;select.value=String(Math.max(base,manualGoals.get(id)||0));for(const option of select.options)option.disabled=Number(option.value)<base;const note=select.closest('label').querySelector('.weapon-skill-note');note.hidden=!base;note.textContent=base?`선택 무기에서 Lv.${base} 자동 적용`:'';}updateChosen();}
 function updateChosen(){const goals=selectedGoals(),intrinsic=intrinsicGoals(),summary=$('buildChosenSkills');summary.replaceChildren();$('buildSelectedCount').textContent=`목표 ${goals.length}개 선택 · 무기 스킬 자동 포함 · 개수 제한 없음`;for(const goal of goals){const skill=data.skills.find(s=>s.id===goal.id),base=intrinsic[goal.id]||0,manual=manualGoals.get(goal.id)||0,button=document.createElement('button');button.type='button';button.textContent=`${skill.name} Lv.${goal.level}${base?' · 무기 자동':''}${manual?' ×':''}`;button.disabled=!manual;button.setAttribute('aria-label',manual?`${skill.name} 직접 선택한 목표 해제`:`${skill.name} 무기에서 자동 적용`);button.addEventListener('click',()=>{manualGoals.delete(goal.id);syncWeaponGoals();invalidate();});summary.append(button);}for(const select of document.querySelectorAll('.build-skill-level'))select.closest('label').classList.toggle('is-selected',Number(select.value)>0);}
 function filterSkills(){const key=$('buildSkillCategories').querySelector('[aria-pressed="true"]')?.dataset.skillCategory||'',needle=normalizeSkill($('buildSkillQuery').value);let count=0;for(const section of document.querySelectorAll('.skill-menu-group')){let visible=0;for(const item of section.querySelectorAll('.skill-menu-item')){item.hidden=Boolean(key&&key!==section.dataset.category)||!item.dataset.search.includes(needle);if(!item.hidden)visible++;}section.hidden=visible===0;count+=visible;}$('buildSkillMatchStatus').textContent=count?`${count}개 스킬 표시 · 필터를 바꿔도 선택한 목표는 유지됩니다.`:'일치하는 스킬이 없습니다. 검색어를 줄이거나 전체 분류를 선택하세요.';}
 function text(parent,tag,value){const el=document.createElement(tag);el.textContent=value;parent.append(el);return el;}
 function render(result){const container=$('buildResults');container.replaceChildren();result.results.forEach((r,i)=>{const entry=document.createElement('details');entry.className='build-result-entry';const summary=document.createElement('summary');const heading=document.createElement('span');heading.className='build-result-heading';text(heading,'strong',`세팅 ${i+1} · ${r.weapon.name}`);text(heading,'span',`최대 강화 방어력 ${r.defense}`);summary.append(heading);const preview=text(summary,'span',r.achieved.map(g=>`${g.name} Lv.${g.level}`).join(' / '));preview.className='build-result-preview';entry.append(summary);const card=document.createElement('article');card.className='build-card';text(card,'h3',`세팅 ${i+1} · 최대 강화 방어력 ${r.defense}`);text(card,'p','방어구 기본 내성: '+[['fire','불'],['water','물'],['thunder','번개'],['ice','얼음'],['dragon','용']].map(([e,label])=>`${label} ${r.resistances[e]>=0?'+':''}${r.resistances[e]}`).join(' / '));text(card,'p',r.achieved.map(g=>`${g.name} Lv.${g.level}${g.pieces!==null?` (${g.pieces}부위)` : ''}`).join(' / '));const list=document.createElement('ul');for(const item of [r.weapon,...r.armor])text(list,'li',`${parts[item.part||'weapon']}: ${item.name} · 슬롯 ${item.slots.join('/')||'없음'}`);card.append(list);if(r.weapon.selectedBonuses?.length)text(card,'p','무기 부여 스킬: '+r.weapon.selectedBonuses.map(b=>`${b.name} · 1부위`).join(' / '));text(card,'p',r.charm?`호석: ${r.charm.skills.map(s=>`${s.name} Lv.${s.level}`).join(' / ')} · 무기 ${r.charm.weaponSlots.join('/')||'없음'} · 방어구 ${r.charm.armorSlots.join('/')||'없음'} · ${r.charmOwned?'보유':'규칙 후보'}`:'호석: 사용하지 않음');if(r.decorations.length){text(card,'h4','장식주 배치');const jewels=document.createElement('ul');for(const p of r.decorations)text(jewels,'li',`${parts[p.owner]} ${p.index+1}번 ${p.kind==='weapon'?'무기':'방어구'} 슬롯[${p.size}]: ${p.decoration.name}`);card.append(jewels);}else text(card,'p','장식주: 필요 없음');if(r.activeBonuses.length)text(card,'p','발동 효과: '+r.activeBonuses.map(b=>`${b.name} — ${b.effect} (${b.pieces}부위)`).join(' / '));const save=document.createElement('button');save.type='button';save.className='primary save-build';save.textContent='이 세팅 저장';save.addEventListener('click',()=>{try{const snapshot=SavedBuilds.snapshot(r,data,$('buildMode').value);if(window.saveBuild(snapshot,`세팅 ${i+1}`)) {save.textContent='저장 완료';save.disabled=true;}}catch(e){$('buildError').textContent=e.message;}});card.append(save);entry.append(card);container.append(entry);});const limits={'result-limit':'대표 결과 20개 도달','time-limit':'20초 제한','node-limit':'탐색량 제한'};$('buildStatus').textContent=`${result.results.length}개 조합 · ${result.partial?`${limits[result.reason]||'제한'}으로 중단. 전체 탐색을 마치지 않았습니다.`:'지원 데이터 범위 검색 완료.'}${!result.results.length?' 조건을 낮추거나 호석 모드를 바꿔 보세요.':''}${result.excludedCharms?` 장비 데이터와 스킬이 맞지 않는 호석 후보 ${result.excludedCharms}건 제외.`:''}`;}
 dialog.addEventListener('page-enter',async()=>{if(data||loading)return;loading=true;$('buildStatus').textContent='장비 데이터를 불러오는 중…';try{const files=await Promise.all(['data/equipment-snapshot.json','data/skill-categories.json'].map(async url=>{const response=await fetch(url);if(!response.ok)throw Error('검색 데이터 요청 실패');return response.json();}));[data,categories]=files;data.weaponOnlySkillIds ||= data.skills.filter(s=>s.kind==='weapon'&&![...data.armor,...data.decorations].some(a=>a.skills[s.id])).map(s=>s.id);for(const [id,kind]of [['buildWeaponSeries','set'],['buildWeaponGroup','group']])for(const skill of data.skills.filter(s=>s.kind===kind).sort((a,b)=>a.name.localeCompare(b.name,'ko')))option($(id),skill.id,`${skill.name} · ${skill.ranks.map(r=>r.name).join(' / ')}`);$('buildSource').textContent=`MHDB 데이터 반영: ${data.apiImportVersion} · 게임 버전 미확인`;for(const [key,value]of Object.entries(types))option($('buildType'),key,value);$('buildType').value='long-sword';weapons();renderSkillMenu();$('buildStart').disabled=false;$('buildStatus').textContent='목표 스킬을 선택하고 검색하세요.';}catch(e){$('buildError').textContent=e.message;}finally{loading=false;}});
 $('buildWeapon').addEventListener('change',weaponHint);$('buildType').addEventListener('change',()=>{weapons();invalidate();});$('buildSkillQuery').addEventListener('input',filterSkills);$('buildClearGoals').addEventListener('click',()=>{manualGoals.clear();syncWeaponGoals();invalidate();});$('buildForm').addEventListener('change',invalidate);
 dialog.addEventListener('page-leave',()=>{if(worker)stop('페이지를 이동하여 검색을 취소했습니다.');});$('buildCancel').addEventListener('click',()=>stop('검색을 취소했습니다.'));let stateVersion=JSON.stringify([CandidateContext.get().inventoryVersion,CandidateContext.get().rulesVersion]);document.addEventListener('inventory-state-changed',()=>{const next=JSON.stringify([CandidateContext.get().inventoryVersion,CandidateContext.get().rulesVersion]);if(next!==stateVersion){stateVersion=next;invalidate();}});
 $('buildForm').addEventListener('submit',event=>{event.preventDefault();stop();$('buildError').textContent='';$('buildResults').replaceChildren();const request={weaponId:Number($('buildWeapon').value),weaponSeriesSkillId:Number($('buildWeaponSeries').value),weaponGroupSkillId:Number($('buildWeaponGroup').value),goals:selectedGoals(),charmMode:$('buildMode').value,minResistances:Object.fromEntries(['fire','water','thunder','ice','dragon'].map(e=>[e,$('buildRes'+e).value===''?null:Number($('buildRes'+e).value)])),minDefense:Number($('buildDefense').value),records:window.CandidateContext.get().records};const token=generation;worker=new Worker('build-worker.js');$('buildStart').disabled=true;$('buildCancel').disabled=false;$('buildStatus').textContent='검색 준비 중…';worker.onmessage=({data:message})=>{if(token!==generation)return;if(message.type==='progress')$('buildStatus').textContent=message.phase==='charms'?`호석 후보 축소 중… ${message.examined||0}개 스킬 배정 확인`:`장비 탐색 중… ${message.nodes}회 / 결과 ${message.results}개`;else{stop();if(message.type==='error')$('buildError').textContent=message.message;else render(message);}};worker.onerror=()=>{stop();$('buildError').textContent='검색 작업을 실행하지 못했습니다. 새로고침 후 다시 시도하세요.';};worker.postMessage(request);});
})();
